internal static class GeneratedEventIdRanges
{
    public const ushort SystemBoundary = (ushort)SystemEventId.E_SYSTEM_EVENT_ID_END;
    public const ushort ClientStart = (ushort)SystemEventId.E_SYSTEM_EVENT_ID_END + 1;
    public const ushort ClientEnd = (ushort)ClientEventId.EGS_CLIENT_EVENT_ID_END;
    public const ushort ServerBoundary = (ushort)ClientEventId.EGS_CLIENT_EVENT_ID_END;
    public const ushort ServerStart = (ushort)ServerEventId.E_SERVER_EVENT_ID_BEGIN + 1;
    public const ushort ServerEnd = (ushort)ServerEventId.E_SERVER_EVENT_ID_END;
}

internal static class GeneratedEventIdNames
{
    public static string? Get(ushort value)
    {
        if (value == (ushort)X2ServerEventId.EVENT_X2_STARTUP)
            return nameof(X2ServerEventId.EVENT_X2_STARTUP);

        if (Enum.IsDefined(typeof(ClientEventId), value))
            return ((ClientEventId)value).ToString();

        if (Enum.IsDefined(typeof(ServerEventId), value))
            return ((ServerEventId)value).ToString();

        if (Enum.IsDefined(typeof(SystemEventId), value))
            return ((SystemEventId)value).ToString();

        return null;
    }
}
